# ── Hilfsfunktionen ───────────────────────────────────────
def log(msg):
    ts = datetime.now().strftime("%H:%M:%S")
    print(f"[{ts}] {msg}", flush=True)

def fetch_wb(indicator: str, iso3_codes: list[str], start: int, end: int) -> dict:
    """Fetcht einen WB-Indikator für alle Länder, gibt {ISO3: {year: value}} zurück."""
    countries = ";".join(iso3_codes)
    url = (f"https://api.worldbank.org/v2/country/{countries}"
           f"/indicator/{indicator}?format=json&per_page=2000&date={start}:{end}")
    try:
        r = requests.get(url, timeout=WB_TIMEOUT,
                         headers={"User-Agent": "data.vlaj.at/pipeline"})
        r.raise_for_status()
        data = r.json()
        if len(data) < 2 or not data[1]:
            return {}
        result = {}
        for row in data[1]:
            if row["value"] is None:
                continue
            iso3 = (row.get("countryiso3code") or row.get("country", {}).get("id", "")).upper()
            year = int(row["date"])
            if iso3 and year:
                result.setdefault(iso3, {})[year] = float(row["value"])
        return result
    except Exception as e:
        log(f"  ⚠ Fehler bei {indicator}: {e}")
        return {}

def apply_fallback(data: dict, cc: str, topic: str, years: list[int]):
    """Füllt None-Werte mit Fallback-Daten."""
    tbl = FB_TOPIC.get(topic)
    if not tbl:
        return
    fb = FALLBACKS.get(tbl, {}).get(cc, [])
    start_idx = years.index(START_YEAR) if START_YEAR in years else 0
    for i, year in enumerate(years):
        if data[cc][topic].get(year) is None:
            fb_idx = (year - START_YEAR)
            if 0 <= fb_idx < len(fb) and fb[fb_idx] is not None:
                data[cc][topic][year] = fb[fb_idx]

def usd_to_eur(usd: float, year: int) -> float:
    """Konvertiert USD → EUR mit Jahresdurchschnitt."""
    idx = min(max(year - START_YEAR, 0), len(EURUSD) - 1)
    return usd / EURUSD[idx]

# ── Hauptprogramm ─────────────────────────────────────────
def main():
    years = list(range(START_YEAR, END_YEAR + 1))
    iso3_list = list(ISO2_TO_3.values())

    log(f"=== Pipeline gestartet: {START_YEAR}–{END_YEAR} ===")
    log(f"Länder: {len(COUNTRIES)}, Indikatoren: {len(WB_INDICATORS)}, Jahre: {len(years)}")

    # Datenstruktur initialisieren
    data = {cc: {} for cc in COUNTRIES}

    # ── 1. Weltbank-Daten fetchen ────────────────────────
    ok, fail = 0, 0
    for wb_code, (topic, dec) in WB_INDICATORS.items():
        log(f"Fetche {wb_code} → {topic}")
        raw = fetch_wb(wb_code, iso3_list, START_YEAR, END_YEAR)

        for cc in COUNTRIES:
            iso3 = ISO2_TO_3[cc]
            data[cc].setdefault(topic, {})
            for year in years:
                val = raw.get(iso3, {}).get(year)
                data[cc][topic][year] = round(val, dec) if val is not None else None

        if raw:
            ok += 1
        else:
            fail += 1
        time.sleep(WB_PAUSE)

    log(f"WB fetch: {ok} OK, {fail} fehlgeschlagen")

    # ── 2. Fallbacks auffüllen ───────────────────────────
    log("Fülle Lücken mit Fallbacks...")
    for cc in COUNTRIES:
        for topic in list(FB_TOPIC.keys()):
            if topic not in data[cc]:
                data[cc][topic] = {y: None for y in years}
            apply_fallback(data, cc, topic, years)

    # ── 3. EUR-Konvertierung ────────────────────────────
    log("Konvertiere USD → EUR...")
    for cc in COUNTRIES:
        # gdppc
        data[cc]["gdppc"] = {}
        for year in years:
            usd = data[cc].get("gdppc_usd", {}).get(year)
            data[cc]["gdppc"][year] = int(usd_to_eur(usd, year)) if usd else None
        # gdpAbs (Milliarden EUR)
        data[cc]["gdpAbs"] = {}
        for year in years:
            usd = data[cc].get("gdpAbs_usd", {}).get(year)
            data[cc]["gdpAbs"][year] = int(usd_to_eur(usd, year) / 1e9) if usd else None
        # Rohdaten entfernen
        data[cc].pop("gdppc_usd", None)
        data[cc].pop("gdpAbs_usd", None)

    # ── 4. Daten als Array (nicht Dict) speichern ───────
    # app.js erwartet Arrays: [val_1990, val_1991, ...]
    countries_out = {}
    for cc in COUNTRIES:
        countries_out[cc] = {}
        for topic, by_year in data[cc].items():
            countries_out[cc][topic] = [by_year.get(y) for y in years]

    # ── 5. Ausgabe ──────────────────────────────────────
    output = {
        "generated": datetime.now(timezone.utc).isoformat(),
        "years":     years,
        "yearStart": START_YEAR,
        "yearEnd":   END_YEAR,
        "countries": countries_out,
    }

    OUTPUT_FILE.parent.mkdir(parents=True, exist_ok=True)
    tmp = OUTPUT_FILE.with_suffix(".json.tmp")
    tmp.write_text(json.dumps(output, ensure_ascii=False, separators=(",", ":")))
    tmp.replace(OUTPUT_FILE)

    size_kb = OUTPUT_FILE.stat().st_size // 1024
    log(f"✓ Fertig! docs/data.json: {size_kb} KB")
    log(f"=== Pipeline abgeschlossen ===")

if __name__ == "__main__":
    main()
